#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Per the reporting rules (HANDOFF.md):
#   - every SKU in movements.log must be listed, even with a net of 0; and
#   - every catalog SKU must appear (SKU-9), even with no movements that day.
awk '
{ net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
END {
    if (!seen["SKU-9"]) net["SKU-9"] = 0
    for (sku in net) print sku, net[sku]
}' \
    movements.log | sort > stock.txt
